using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;
/// <summary>Driving touch UI: left-side steering and hold-to-accelerate/brake.</summary>
public class StreetLegendDrivingHUD:MonoBehaviour{
 public StreetLegendVehicleController vehicle;bool gas,brake;float steer;int steeringFinger=-1;Vector2 steeringStart;
 void Start(){if(!vehicle)vehicle=FindObjectOfType<StreetLegendVehicleController>();Build();}
 void Update(){if(!vehicle)return;for(int i=0;i<Input.touchCount;i++){Touch t=Input.GetTouch(i);if(t.phase==TouchPhase.Began&&t.position.x<Screen.width*.5f&&steeringFinger<0){steeringFinger=t.fingerId;steeringStart=t.position;}if(t.fingerId==steeringFinger){if(t.phase==TouchPhase.Moved||t.phase==TouchPhase.Stationary)steer=Mathf.Clamp((t.position.x-steeringStart.x)/(Screen.width*.22f),-1,1);if(t.phase==TouchPhase.Ended||t.phase==TouchPhase.Canceled){steeringFinger=-1;steer=0;}}}vehicle.SetInput(steer,gas?1:0,brake);}
 void Build(){var go=new GameObject("Driving HUD Canvas",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));go.transform.SetParent(transform,false);var c=go.GetComponent<Canvas>();c.renderMode=RenderMode.ScreenSpaceOverlay;c.sortingOrder=25;var sc=go.GetComponent<CanvasScaler>();sc.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;sc.referenceResolution=new Vector2(1920,1080);if(!FindObjectOfType<EventSystem>())new GameObject("EventSystem",typeof(EventSystem),typeof(StandaloneInputModule));MakeHold(go.transform,"ACCEL",new Vector2(.88f,.2f),true);MakeHold(go.transform,"BRAKE",new Vector2(.72f,.2f),false);}
 void MakeHold(Transform p,string label,Vector2 a,bool acceleration){var g=new GameObject(label,typeof(RectTransform),typeof(Image),typeof(Button),typeof(StreetLegendDriveHold));g.transform.SetParent(p,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=a;r.sizeDelta=new Vector2(180,150);g.GetComponent<Image>().color=new Color(.08f,.2f,.32f,.8f);g.GetComponent<StreetLegendDriveHold>().Configure(this,acceleration);var txt=new GameObject("Label",typeof(RectTransform),typeof(Text));txt.transform.SetParent(g.transform,false);var tr=txt.GetComponent<RectTransform>();tr.anchorMin=Vector2.zero;tr.anchorMax=Vector2.one;tr.offsetMin=tr.offsetMax=Vector2.zero;var t=txt.GetComponent<Text>();t.text=label;t.font=Resources.GetBuiltinResource<Font>("Arial.ttf");t.fontSize=28;t.alignment=TextAnchor.MiddleCenter;t.color=Color.white;t.raycastTarget=false;}
 public void Hold(bool acceleration,bool value){if(acceleration)gas=value;else brake=value;}
 void OnDisable(){gas=false;brake=false;steer=0;steeringFinger=-1;if(vehicle)vehicle.SetInput(0,0,false);}
}
public class StreetLegendDriveHold:MonoBehaviour,IPointerDownHandler,IPointerUpHandler,IPointerExitHandler{
 StreetLegendDrivingHUD owner;bool acceleration;public void Configure(StreetLegendDrivingHUD o,bool gas){owner=o;acceleration=gas;}public void OnPointerDown(PointerEventData e){if(owner)owner.Hold(acceleration,true);}public void OnPointerUp(PointerEventData e){if(owner)owner.Hold(acceleration,false);}public void OnPointerExit(PointerEventData e){if(owner)owner.Hold(acceleration,false);}
}
